document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('quiz-form');
    const resultsDiv = document.getElementById('results');

    const correctAnswers = {
        q1: ['java', 'cpp'],
        q2: ['c', 'python'],
        q3: ['kotlin', 'swift', 'dart']
    };

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const formData = new FormData(form);
        const userAnswers = {
            q1: formData.getAll('q1'),
            q2: formData.getAll('q2'),
            q3: formData.getAll('q3')
        };

        let score = 0;
        const totalQuestions = Object.keys(correctAnswers).length;

        for (const q in correctAnswers) {
            const userSet = new Set(userAnswers[q]);
            const correctSet = new Set(correctAnswers[q]);

            if (userSet.size === correctSet.size && [...userSet].every(val => correctSet.has(val))) {
                score++;
            }
        }

        resultsDiv.textContent = `You scored ${score} out of ${totalQuestions}!`;

        if (score === totalQuestions) {
            resultsDiv.className = 'correct';
        } else {
            resultsDiv.className = 'incorrect';
        }

        // Ensure screen reader users hear the result immediately
        resultsDiv.focus(); 
    });
});

